// Cada método ordena una COPIA y devuelve cuántas comparaciones e intercambios (o movimientos) hizo.
function burbuja(entrada) {
  const a = entrada.slice(); let comp = 0, mov = 0;
  for (let pasada = 0; pasada < a.length - 1; pasada++) {
    let hubo = false;
    for (let j = 0; j < a.length - 1 - pasada; j++) {   // lo de la derecha ya quedó en su lugar
      comp++;
      if (a[j] > a[j + 1]) { [a[j], a[j + 1]] = [a[j + 1], a[j]]; mov++; hubo = true; }
    }
    if (!hubo) break;                                    // una pasada sin intercambios: ya está
  }
  return { a, comp, mov };
}

function seleccion(entrada) {
  const a = entrada.slice(); let comp = 0, mov = 0;
  for (let i = 0; i < a.length - 1; i++) {
    let m = i;                                           // posición del menor de a[i..]
    for (let j = i + 1; j < a.length; j++) { comp++; if (a[j] < a[m]) m = j; }
    if (m !== i) { [a[i], a[m]] = [a[m], a[i]]; mov++; }
  }
  return { a, comp, mov };
}

function insercion(entrada) {
  const a = entrada.slice(); let comp = 0, mov = 0;
  for (let i = 1; i < a.length; i++) {
    const x = a[i]; let j = i - 1;                       // a[0..i-1] ya está ordenado
    while (j >= 0) {
      comp++;
      if (a[j] > x) { a[j + 1] = a[j]; mov++; j--; }     // corro a la derecha lo que es mayor que x
      else break;
    }
    a[j + 1] = x;
  }
  return { a, comp, mov };
}

// Cuenta pares fuera de orden (a[i] > a[j] con i < j): las «inversiones»
const inversiones = a => { let k = 0; for (let i = 0; i < a.length; i++) for (let j = i + 1; j < a.length; j++) if (a[i] > a[j]) k++; return k; };

const ejemplo = [5, 2, 6, 1, 4, 3];
console.log("ejemplo", ejemplo.join(" "), "| inversiones:", inversiones(ejemplo));
for (const [nombre, f] of [["burbuja", burbuja], ["selección", seleccion], ["inserción", insercion]]) {
  const r = f(ejemplo);
  console.log(nombre.padEnd(10), r.a.join(" "), `| comparaciones: ${r.comp}, movimientos: ${r.mov}`);
}

// Tres entradas de 2.000 elementos: aleatoria, ya ordenada e invertida
let semilla = 7;
const azar = () => (semilla = (semilla * 1103515245 + 12345) % 2147483648) / 2147483648;
const n = 2000;
const casos = {
  "aleatoria": Array.from({ length: n }, () => Math.floor(azar() * 100000)),
  "ordenada ": Array.from({ length: n }, (_, i) => i),
  "invertida": Array.from({ length: n }, (_, i) => n - i),
};
for (const [nombre, datos] of Object.entries(casos)) {
  console.log(`--- ${nombre}, n = ${n}, inversiones = ${inversiones(datos)}`);
  for (const [met, f] of [["burbuja", burbuja], ["selección", seleccion], ["inserción", insercion]]) {
    const r = f(datos);
    const bien = r.a.every((v, i) => i === 0 || r.a[i - 1] <= v);
    console.log(`${met.padEnd(10)} comparaciones: ${String(r.comp).padStart(8)}  movimientos: ${String(r.mov).padStart(8)}  ordenó bien: ${bien}`);
  }
}
